mapper.select:
SELECT dataTable.tenant_id AS 'tenantId', dataTable.province_code AS 'provinceCode', dataTable.city_code AS 'cityCode', dataTable.county_code AS 'countyCode', dataTable.device_code AS 'deviceCode', dataTable.industry_code AS 'industryCode', dataTable.task_id AS 'taskId' FROM ${param.tableName} AS dataTable WHERE dataTable.delete_flag = '0' AND dataTable.task_id IS NOT NULL
and dataTable.alarm_time >= #{param.alarmTimeStart}
and dataTable.alarm_time <= #{param.alarmTimeEnd}
GROUP BY dataTable.tenant_id, dataTable.industry_code, dataTable.province_code, dataTable.city_code, dataTable.county_code, dataTable.device_code, dataTable.task_id
